contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData) public payable {
        require(msg.sender != address(address(c)));

        bool reverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Since msg.sender is this test contract, which is not the optimistic asserter,
        // the call must revert. If the caller were the optimistic asserter, it would succeed.
        // We cannot make the test contract be the optimistic asserter because c was deployed by this contract,
        // so address(this) != address(optimisticAsserter). Thus the general rule is: any non-optimistic-asserter caller reverts.
        assert(reverted == true);
    }

    receive() external payable {}
}

